func (this *ToolItem) WidgetStyle() int32 {
	if (this.style & DROP_DOWN) != 0 {
		return win32.OSBTNS_DROPDOWN
	}
	if (this.style & PUSH) != 0 {
		return win32.OSBTNS_BUTTON
	}
	if (this.style & CHECK) != 0 {
		return win32.OSBTNS_CHECK
	}
	if (this.style & RADIO) != 0 {
		return win32.OSBTNS_CHECK
	}
	if (this.style & SEPARATOR) != 0 {
		return win32.OSBTNS_SEP
	}
	return win32.OSBTNS_BUTTON
}

func (this *ToolItem) WmCommandChild(wParam int64, lParam int64) *win32.LRESULT {
	if (this.style & RADIO) != 0 {
		if (this.parent.impl.getStyle_() & NO_RADIO_GROUP) == 0 {
			this.SelectRadio()
		}
	}
	this.SendSelectionEvent(Selection)
	return nil
}

func ToolItemCheckStyle(style int32) int32 {
	return WidgetCheckBits(style, PUSH, CHECK, RADIO, SEPARATOR, DROP_DOWN, 0)
}

func upcastToolBarToComposite(x *ToolBar) *Composite {
	if x == nil {
		return nil
	}
	return &x.Composite
}
